CREATE TABLE users (
 id BIGINT PRIMARY KEY AUTO_INCREMENT, email VARCHAR(254) NOT NULL UNIQUE, name VARCHAR(100) NOT NULL,
 password_hash VARCHAR(100) NOT NULL, role VARCHAR(20) NOT NULL DEFAULT 'CUSTOMER',
 enabled BOOLEAN NOT NULL DEFAULT TRUE, verified BOOLEAN NOT NULL DEFAULT FALSE,
 created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE account_tokens (id BIGINT PRIMARY KEY AUTO_INCREMENT,user_id BIGINT NOT NULL, token_hash CHAR(64) UNIQUE NOT NULL,
 purpose VARCHAR(20) NOT NULL, expires_at TIMESTAMP NOT NULL, used_at TIMESTAMP NULL,
 FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE categories (id BIGINT PRIMARY KEY AUTO_INCREMENT,name VARCHAR(100) NOT NULL,slug VARCHAR(120) UNIQUE NOT NULL);
CREATE TABLE tags (id BIGINT PRIMARY KEY AUTO_INCREMENT,name VARCHAR(100) NOT NULL UNIQUE);
CREATE TABLE collections (id BIGINT PRIMARY KEY AUTO_INCREMENT,name VARCHAR(100) NOT NULL,slug VARCHAR(120) UNIQUE NOT NULL);
CREATE TABLE licenses (id BIGINT PRIMARY KEY AUTO_INCREMENT,version VARCHAR(50) NOT NULL UNIQUE,body TEXT NOT NULL);
CREATE TABLE media_assets (id CHAR(36) PRIMARY KEY,kind VARCHAR(20) NOT NULL,storage_key VARCHAR(100) NOT NULL UNIQUE,
 original_name VARCHAR(255) NOT NULL,mime_type VARCHAR(100) NOT NULL,size_bytes BIGINT NOT NULL,checksum CHAR(64) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE products (id BIGINT PRIMARY KEY AUTO_INCREMENT,name VARCHAR(160) NOT NULL,slug VARCHAR(180) UNIQUE NOT NULL,
 description TEXT NOT NULL,price DECIMAL(18,2) NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'DRAFT',
 category_id BIGINT NOT NULL,width INT NOT NULL,height INT NOT NULL,fps DECIMAL(6,3) NOT NULL,format VARCHAR(20) NOT NULL,
 alpha_channel BOOLEAN NOT NULL DEFAULT FALSE,duration_seconds DECIMAL(10,2) NOT NULL,featured BOOLEAN NOT NULL DEFAULT FALSE,
 thumbnail_id CHAR(36),preview_id CHAR(36),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
 FOREIGN KEY(category_id) REFERENCES categories(id), FOREIGN KEY(thumbnail_id) REFERENCES media_assets(id), FOREIGN KEY(preview_id) REFERENCES media_assets(id));
CREATE INDEX idx_products_catalog ON products(status,category_id,price);
CREATE TABLE product_asset_versions (id BIGINT PRIMARY KEY AUTO_INCREMENT,product_id BIGINT NOT NULL,asset_id CHAR(36) NOT NULL,
 version_number INT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
 UNIQUE(product_id,version_number),FOREIGN KEY(product_id) REFERENCES products(id),FOREIGN KEY(asset_id) REFERENCES media_assets(id));
CREATE TABLE product_tags (product_id BIGINT NOT NULL,tag_id BIGINT NOT NULL,PRIMARY KEY(product_id,tag_id),FOREIGN KEY(product_id) REFERENCES products(id),FOREIGN KEY(tag_id) REFERENCES tags(id));
CREATE TABLE product_collections (product_id BIGINT NOT NULL,collection_id BIGINT NOT NULL,PRIMARY KEY(product_id,collection_id),FOREIGN KEY(product_id) REFERENCES products(id),FOREIGN KEY(collection_id) REFERENCES collections(id));
CREATE TABLE cart_items (user_id BIGINT NOT NULL,product_id BIGINT NOT NULL,PRIMARY KEY(user_id,product_id),FOREIGN KEY(user_id) REFERENCES users(id),FOREIGN KEY(product_id) REFERENCES products(id));
CREATE TABLE orders (id CHAR(36) PRIMARY KEY,user_id BIGINT NOT NULL,email VARCHAR(254) NOT NULL,currency CHAR(3) NOT NULL,
 total DECIMAL(18,2) NOT NULL,status VARCHAR(30) NOT NULL DEFAULT 'PENDING_PAYMENT',idempotency_key VARCHAR(100) NOT NULL,
 created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,expires_at TIMESTAMP NOT NULL,UNIQUE(user_id,idempotency_key),FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE order_items (id BIGINT PRIMARY KEY AUTO_INCREMENT,order_id CHAR(36) NOT NULL,product_id BIGINT NOT NULL,asset_version_id BIGINT NOT NULL,
 name VARCHAR(160) NOT NULL,price DECIMAL(18,2) NOT NULL,license_version VARCHAR(50) NOT NULL,license_body TEXT NOT NULL,
 FOREIGN KEY(order_id) REFERENCES orders(id),FOREIGN KEY(product_id) REFERENCES products(id),FOREIGN KEY(asset_version_id) REFERENCES product_asset_versions(id),UNIQUE(order_id,product_id));
CREATE TABLE download_entitlements (id CHAR(36) PRIMARY KEY,user_id BIGINT NOT NULL,order_item_id BIGINT NOT NULL UNIQUE,status VARCHAR(20) NOT NULL DEFAULT 'ACTIVE',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
 FOREIGN KEY(user_id) REFERENCES users(id),FOREIGN KEY(order_item_id) REFERENCES order_items(id));
CREATE TABLE download_grants (id CHAR(36) PRIMARY KEY,entitlement_id CHAR(36) NOT NULL,token_hash CHAR(64) UNIQUE NOT NULL,expires_at TIMESTAMP NOT NULL,revoked BOOLEAN NOT NULL DEFAULT FALSE,FOREIGN KEY(entitlement_id) REFERENCES download_entitlements(id));
CREATE TABLE download_audit (id BIGINT PRIMARY KEY AUTO_INCREMENT,user_id BIGINT NOT NULL,entitlement_id CHAR(36) NOT NULL,action VARCHAR(30) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE email_jobs (id CHAR(36) PRIMARY KEY,recipient VARCHAR(254) NOT NULL,subject VARCHAR(255) NOT NULL,body TEXT NOT NULL,
 status VARCHAR(20) NOT NULL DEFAULT 'PENDING',attempts INT NOT NULL DEFAULT 0,next_attempt TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
 lease_until TIMESTAMP NULL,last_error VARCHAR(500),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX idx_email_due ON email_jobs(status,next_attempt);
CREATE TABLE email_attempts (id BIGINT PRIMARY KEY AUTO_INCREMENT,job_id CHAR(36) NOT NULL,success BOOLEAN NOT NULL,error_code VARCHAR(100),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(job_id) REFERENCES email_jobs(id));
CREATE TABLE admin_audit (id BIGINT PRIMARY KEY AUTO_INCREMENT,actor VARCHAR(254) NOT NULL,action VARCHAR(80) NOT NULL,target VARCHAR(150) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE SPRING_SESSION (PRIMARY_ID CHAR(36) NOT NULL,SESSION_ID CHAR(36) NOT NULL,CREATION_TIME BIGINT NOT NULL,LAST_ACCESS_TIME BIGINT NOT NULL,MAX_INACTIVE_INTERVAL INT NOT NULL,EXPIRY_TIME BIGINT NOT NULL,PRINCIPAL_NAME VARCHAR(254),CONSTRAINT SPRING_SESSION_PK PRIMARY KEY(PRIMARY_ID));
CREATE UNIQUE INDEX SPRING_SESSION_IX1 ON SPRING_SESSION(SESSION_ID);
CREATE INDEX SPRING_SESSION_IX2 ON SPRING_SESSION(EXPIRY_TIME);
CREATE INDEX SPRING_SESSION_IX3 ON SPRING_SESSION(PRINCIPAL_NAME);
CREATE TABLE SPRING_SESSION_ATTRIBUTES (SESSION_PRIMARY_ID CHAR(36) NOT NULL,ATTRIBUTE_NAME VARCHAR(200) NOT NULL,ATTRIBUTE_BYTES BLOB NOT NULL,CONSTRAINT SPRING_SESSION_ATTRIBUTES_PK PRIMARY KEY(SESSION_PRIMARY_ID,ATTRIBUTE_NAME),CONSTRAINT SPRING_SESSION_ATTRIBUTES_FK FOREIGN KEY(SESSION_PRIMARY_ID) REFERENCES SPRING_SESSION(PRIMARY_ID) ON DELETE CASCADE);
